### Step 4: Codebook with durable storage (`src/similarity/codebook.rs`)

In-memory HashMap backed by durable SQLite table. Loads existing entries on init, generates new random vectors for unknown keys, tracks new entries for batch-save.

```rust
// src/similarity/codebook.rs
use super::hrr::{HrrVec, Rng, DEFAULT_DIM};
use std::collections::HashMap;

pub struct Codebook {
    entries: HashMap<String, HrrVec>,
    new_keys: Vec<String>,  // keys added this session, pending save
    rng: Rng,
}

impl Codebook {
    /// Load existing entries from DB, init RNG for new entries
    pub fn load(conn: &rusqlite::Connection) -> Result<Self> {
        let mut stmt = conn.prepare("SELECT key, vector FROM hrr_codebook")?;
        let mut entries = HashMap::new();
        let mut rows = stmt.query([])?;
        while let Some(row) = rows.next()? {
            let key: String = row.get(0)?;
            let blob: Vec<u8> = row.get(1)?;
            entries.insert(key, HrrVec::from_bytes(&blob));
        }
        // Seed derived from entry count for reproducibility after restarts
        // (new entries always get fresh vectors, determinism comes from persistence)
        let seed = 0x5554_5241 ^ (entries.len() as u64);
        Ok(Self { entries, new_keys: Vec::new(), rng: Rng::new(seed) })
    }

    pub fn get_or_create(&mut self, key: &str) -> HrrVec {
        if let Some(v) = self.entries.get(key) {
            return v.clone();
        }
        let v = HrrVec::random(&mut self.rng);
        self.entries.insert(key.to_string(), v.clone());
        self.new_keys.push(key.to_string());
        v
    }

    /// Persist only new entries (append-only)
    pub fn save_new(self, conn: &rusqlite::Connection) -> Result<usize> {
        let mut stmt = conn.prepare(
            "INSERT OR IGNORE INTO hrr_codebook (key, vector) VALUES (?1, ?2)"
        )?;
        for key in &self.new_keys {
            let vec = &self.entries[key];
            stmt.execute(rusqlite::params![key, vec.to_bytes()])?;
        }
        Ok(self.new_keys.len())
    }
}
```

### Step 5: Recursive encoder (`src/similarity/encoder.rs`)

Port of `hrr-spike.rs::encode_hrr`. Two modes: strip (ignores identifier text) and embed (binds identifier names). Operates on tree-sitter subtrees.

```rust
// src/similarity/encoder.rs
use super::codebook::Codebook;
use super::hrr::{self, HrrVec};

const MAX_DEPTH: usize = 20;

pub fn encode_subtree(
    node: &tree_sitter::Node,
    source: &[u8],
    codebook: &mut Codebook,
    embed_idents: bool,
) -> HrrVec {
    encode_recursive(node, source, codebook, MAX_DEPTH, embed_idents)
}

fn encode_recursive(
    node: &tree_sitter::Node,
    source: &[u8],
    codebook: &mut Codebook,
    depth: usize,
    embed_idents: bool,
) -> HrrVec {
    let kind_vec = codebook.get_or_create(node.kind());

    if depth == 0 || node.child_count() == 0 {
        if embed_idents
            && (node.kind() == "identifier" || node.kind() == "type_identifier")
        {
            if let Ok(text) = node.utf8_text(source) {
                let name_vec = codebook.get_or_create(&format!("id:{text}"));
                return kind_vec.bind(&name_vec);
            }
        }
        return kind_vec;
    }

    let mut child_vecs = Vec::with_capacity(node.child_count());
    let mut pos = 0usize;
    for i in 0..node.child_count() {
        let child = node.child(i).unwrap();
        if !child.is_named() { continue; }
        let child_enc = encode_recursive(&child, source, codebook, depth - 1, embed_idents);
        child_vecs.push(child_enc.permute(pos + 1));
        pos += 1;
    }

    if child_vecs.is_empty() {
        return kind_vec;
    }

    let bundled = hrr::bundle(&child_vecs);
    kind_vec.bind(&bundled)
}
```

