// src/db/similarity.rs
use crate::error::Result;
use super::Db;

/// Row for a function symbol needing HRR encoding
pub struct HrrSymbolRow {
    pub symbol_id: i64,
    pub file_path: String,
    pub language: String,
    pub start_line: i64,
    pub start_col: i64,
    pub end_line: i64,
    pub end_col: i64,
}

impl Db {
    /// All function/method symbols with their file paths, for HRR encoding.
    pub fn function_symbols_for_hrr(&self) -> Result<Vec<HrrSymbolRow>> {
        let conn = self.conn.lock();
        let mut stmt = conn.prepare(
            "SELECT s.id, f.path, f.language,
                    s.start_line, s.start_col, s.end_line, s.end_col
             FROM symbols s JOIN files f ON s.file_id = f.id
             WHERE s.kind IN ('function', 'method')"
        )?;
        // ... map rows ...
    }

    pub fn replace_hrr_vectors(&self, vectors: &[(i64, &str, &[u8])]) -> Result<()> {
        let conn = self.conn.lock();
        conn.execute("DELETE FROM hrr_vectors", [])?;
        let mut stmt = conn.prepare(
            "INSERT INTO hrr_vectors (symbol_id, mode, vector) VALUES (?1, ?2, ?3)"
        )?;
        for (sym_id, mode, blob) in vectors {
            stmt.execute(rusqlite::params![sym_id, mode, blob])?;
        }
        Ok(())
    }
}
```

### Step 7: Entry point + pipeline integration (`src/similarity/mod.rs`, `src/pipeline.rs`)

The entry point loads the codebook, queries function symbols, groups by file, re-parses each with tree-sitter, encodes, stores. Pipeline calls it after health findings.

```rust
// src/similarity/mod.rs
pub mod codebook;
pub mod encoder;
pub mod hrr;

use crate::db::Db;
use crate::error::Result;
use crate::parser::adapter::LanguageRegistry;
use std::path::Path;

pub fn compute_hrr_vectors(db: &Db, workspace_root: &Path) -> Result<usize> {
    let symbols = db.function_symbols_for_hrr()?;
    if symbols.is_empty() { return Ok(0); }

    let conn = db.conn.lock();
    let mut codebook = codebook::Codebook::load(&conn)?;
    drop(conn);

    let registry = LanguageRegistry::new_with_defaults();
    // Group symbols by file path
    let mut by_file: HashMap<String, Vec<&HrrSymbolRow>> = HashMap::new();
    for sym in &symbols { by_file.entry(sym.file_path.clone()).or_default().push(sym); }

    let mut vectors: Vec<(i64, String, Vec<u8>)> = Vec::new();

    for (path, file_symbols) in &by_file {
        let full_path = workspace_root.join(path);
        let source = std::fs::read_to_string(&full_path)?; // already indexed, must exist
        let adapter = match registry.adapter_for_language(&file_symbols[0].language) {
            Some(a) => a,
            None => continue,
        };
        let mut parser = tree_sitter::Parser::new();
        parser.set_language(&adapter.grammar())?;
        let tree = parser.parse(&source, None)
            .ok_or_else(|| SutraError::Parse("re-parse failed".into()))?;

        for sym in file_symbols {
            let start = tree_sitter::Point::new(sym.start_line as usize, sym.start_col as usize);
            let end = tree_sitter::Point::new(sym.end_line as usize, sym.end_col as usize);
            let node = tree.root_node().descendant_for_point_range(start, end);
            if let Some(node) = node {
                // strip mode
                let strip_vec = encoder::encode_subtree(&node, source.as_bytes(), &mut codebook, false);
                vectors.push((sym.symbol_id, "strip".into(), strip_vec.to_bytes()));
                // embed mode
                let embed_vec = encoder::encode_subtree(&node, source.as_bytes(), &mut codebook, true);
                vectors.push((sym.symbol_id, "embed".into(), embed_vec.to_bytes()));
            }
        }
    }

    let vec_refs: Vec<(i64, &str, &[u8])> = vectors.iter()
        .map(|(id, mode, blob)| (*id, mode.as_str(), blob.as_slice()))
        .collect();
    db.replace_hrr_vectors(&vec_refs)?;

    let conn = db.conn.lock();
    codebook.save_new(&conn)?;

    Ok(vectors.len() / 2) // symbol count (2 vectors per symbol)
}
```

